import math

def is_square(n):
    if n < 0: return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n*sqrt_n == n

min_val = float('inf')
best_pair = None

for d in range(1, 1000):
    for c in range(d, 2000):
        m2 = c*c - 6*c*d + d*d
        if m2 > 0 and is_square(m2):
            val = (c*c + d*d) / (c*d)
            if val < min_val:
                min_val = val
                best_pair = (c, d)

print(f"Min val: {min_val}, Best pair: {best_pair}")
